import{d as p,C as s,o as g,c as d,a3 as t,E as i,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第四十二章","description":"《正易心法》第四十二章——世俗学解，浸渍旧闻：以《春秋》与《左传》为比，说学者玩其文辞而本经微旨泯；不知借辞以明画象，遂溺其辞，加以古今训注而袭谬承误，使羲皇初意不行于世——「呜乎！」","frontmatter":{"title":"正易心法·第四十二章","description":"《正易心法》第四十二章——世俗学解，浸渍旧闻：以《春秋》与《左传》为比，说学者玩其文辞而本经微旨泯；不知借辞以明画象，遂溺其辞，加以古今训注而袭谬承误，使羲皇初意不行于世——「呜乎！」","category":"guide","aliases":["正易心法第四十二章","世俗学解浸渍旧闻","呜乎"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-42.md","filePath":"yijing/zheng-yi-xin-fa/chapter-42.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-42.md"},x=p({...c,setup(u){const e=[{id:"z42-01",label:"一、世俗学解",showLabel:!0,sentences:[["世俗学解，",{text:"浸渍旧闻",glossary:"jinziJiuwen"},"。失其",{text:"本始",glossary:"benshi"},"，易道",{text:"浅狭",glossary:"qianxia"},"。"]],note:["世俗的学问解读，浸泡在旧有的见闻里；失去了根本与起始，易道因此变得浅薄狭窄。（**「本始」＝羲皇画卦的初意。** 这是全书正文的最后一章，也是**批评的收口**：从第一章「不知落处」到此处的「失其本始」，**麻衣批的是同一件事——把活的做成死的。**）"]},{id:"z42-02",label:"二、春秋与左氏之比",showLabel:!0,sentences:[["羲皇氏正《易》，《春秋》比也。周、孔明《易》，作传比也。左氏本为《春秋》作传，而世乃玩其文辞，致左氏",{text:"孤行",glossary:"guxing"},"，而《春秋》之",{text:"微旨",glossary:"weizhi"},"泯矣。"]],note:["伏羲创制《易》，就像《春秋》的地位；周文王、周公、孔子阐明《易》，就像为《春秋》作传。《左传》本来是为《春秋》作传的，但世人只是玩味《左传》的文辞，导致《左传》单独流行，而《春秋》深微的宗旨就消失了。（**这个类比极有说服力**：《春秋》本经字数少、一字褒贬；《左传》文采斐然、故事生动——**结果人人读《左传》，《春秋》被冷落。** 麻衣用它说：**《易》的处境一模一样，卦画（本经）被卦辞（传）淹没了。**）"]},{id:"z42-03",label:"三、易之有辞",showLabel:!0,sentences:[["《易》之有辞，本为羲皇发扬。学者不知",{text:"借辞以明其画象",glossary:"jieciMingxiang"},"，遂",{text:"溺其辞",glossary:"niqici"},"，"]],note:["《易》有文辞，本来是为了发扬伏羲的卦象；学者不知道应该借助文辞来阐明卦画之象，反而沉溺于文辞。（**正确顺序**：画象（主）→ 文辞（从）→ 借辞以明画象。**错误顺序**：文辞（主）→ 溺其辞 → 离画象越来越远。**辞是过河的桥，过了桥要到彼岸，不是要在桥上盖房子。**）"]},{id:"z42-04",label:"四、袭谬承误",showLabel:!0,sentences:[["加以古今训注而",{text:"袭谬承误",glossary:"ximiuChengwu"},"，使",{text:"羲皇初意",glossary:"xihuangChuyi"},"不行于世，而《易》道于此浅狭矣。"]],note:["加上历代的训诂注释，一代代沿袭错误、继承谬误，使得伏羲最初的意图不能流行于世，《易》道就在这里变得浅薄狭窄了。（**这是一个「雪球效应」**：第一代（羲皇画卦、周孔作辞）失真一次；此后**汉儒注经、魏晋注汉儒、唐人注魏晋、宋人注唐人**——每层注解都在解释上一层，同时也遮蔽上一层。**麻衣不是批评某一个注家，他批评的是这个机制本身**：每一代人都在认真传递，但传递的过程本身就是失真的过程。）"]},{id:"z42-05",label:"五、呜乎",showLabel:!0,sentences:[[{text:"呜乎",glossary:"wuhu"},"！"]],note:["唉——！（**这是全书唯一的感叹词。** 前四十一章麻衣的语气一贯是：「此之谓也」（肯定）、「失之甚矣」（批评）、「是为定论」（确认）、「颇得之」（评价）——**冷静，克制，精准。** 而这一章的最后，他写了「呜乎」：**不是愤怒，不是绝望，是一种深沉的、无可奈何的悲悯。** 他看见了羲皇初意，也知道那个初意在他的时代已经「不行于世」；**而他写的这四十二章，也是文字，也可能成为下一代人「袭谬承误」的材料。** 这是**一个清醒者的叹息**。）"]}],o=[{id:"jinziJiuwen",term:"浸渍旧闻",pinyin:"jìn zì jiù wén",meaning:"浸泡在旧有的见闻里。浸渍＝浸泡渗透；旧闻＝前人的说法。"},{id:"benshi",term:"本始",pinyin:"běn shǐ",meaning:"根本与起始。本始＝羲皇画卦的初意。"},{id:"qianxia",term:"浅狭",pinyin:"qiǎn xiá",meaning:"浅薄狭窄。《易》道本来宽广，被学者弄得浅薄了。"},{id:"guxing",term:"孤行",pinyin:"gū xíng",meaning:"单独流行。脱离了本经而独立流传。"},{id:"weizhi",term:"微旨",pinyin:"wēi zhǐ",meaning:"深微的宗旨。《春秋》的真意被《左传》的文辞遮蔽。"},{id:"jieciMingxiang",term:"借辞以明其画象",pinyin:"jiè cí yǐ míng",meaning:"借助文辞来阐明卦画之象。辞是手段，象是目的。"},{id:"niqici",term:"溺其辞",pinyin:"nì qí cí",meaning:"沉溺于文辞。把手段当成了目的。"},{id:"ximiuChengwu",term:"袭谬承误",pinyin:"xí miù chéng wù",meaning:"沿袭错误、继承谬误。一代代把错误当正确传下去。"},{id:"xihuangChuyi",term:"羲皇初意",pinyin:"xī huáng chū yì",meaning:"伏羲最初的意图。画卦时那个直接感知天地的心地。"},{id:"wuhu",term:"呜乎",pinyin:"wū hū",meaning:"叹词。全书唯一的感叹，沉痛之极。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",20)),i(r,{colophon:"世俗学解 · 春秋之比 · 借辞明象 · 呜乎",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四十二章原文",sections:e,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(l,{items:[{term:"浸渍旧闻",pinyin:["jìn","zì"],meaning:"浸泡在旧有的见闻里——只知传述，不知本始。"},{term:"春秋之比",pinyin:["chūn","qiū"],meaning:"《春秋》本经被《左传》的文辞淹没，《易》的卦画也被卦辞淹没——两个系统犯了同一个错误。"},{term:"借辞以明其画象",pinyin:["jiè","cí"],meaning:"借助文辞来阐明卦画之象。辞是过河的桥，过了桥要到彼岸，不是在桥上盖房子。"},{term:"袭谬承误",pinyin:["xí","miù"],meaning:"一代代沿袭错误。每一代人都在认真传递，但传递的过程本身就是失真的过程——雪球效应。"},{term:"呜乎",pinyin:["wū","hū"],meaning:"全书唯一的感叹词。不是愤怒或绝望，而是一个清醒者的悲悯与叹息。"}]}),n[3]||(n[3]=t("",24))])}}});export{y as __pageData,x as default};
